const libstd=@import("std");
const nt=@import("ntfs_ro");
// Synthetic bytes are generated by our existing writer helpers, not extracted
// NT5 source/binaries. Field identities follow NT5 ntfs.h; malformed references
// must fail without a recursive retry or a write callback.
const MftFixture = struct {
    bytes: [262144]u8 = @splat(0),
    fn read(ctx: *anyopaque, at: u64, out: []u8) error{Io,OutOfBounds}!void {
        const self: *MftFixture = @ptrCast(@alignCast(ctx));
        if (out.len>65536 or at > self.bytes.len or out.len > self.bytes.len - at) return error.OutOfBounds;
        @memcpy(out, self.bytes[@intCast(at)..][0..out.len]);
    }
    fn reader(self: *MftFixture) nt.Reader { return .{ .context = self, .read_fn = read }; }
    fn put(comptime T: type, out: []u8, at: usize, value: T) void { libstd.mem.writeInt(T, out[at..][0..@sizeOf(T)], value, .little); }
    fn init(nonresident: bool, bad_sequence: bool, bad_base: bool, gap: bool) !MftFixture {
        const r = @import("record.zig");
        var f: MftFixture = .{};
        @memcpy(f.bytes[3..11], "NTFS    ");
        put(u16, &f.bytes, 11, 512); f.bytes[13] = 8;
        put(u64, &f.bytes, 40, 512); put(u64, &f.bytes, 48, 1); put(u64, &f.bytes, 56, 15);
        f.bytes[64] = 0xf6; f.bytes[68] = 1; put(u16, &f.bytes, 510, 0xaa55);
        var list: [64]u8 = @splat(0);
        for (0..2) |i| {
            const e = list[i*32..][0..32];
            put(u32,e,0,0x80);put(u16,e,4,32);
            put(u64,e,8,if(i==0) 0 else if(gap) 3 else 2);
            put(u64,e,16,(@as(u64,if(bad_sequence and i==1) 2 else 1)<<48)|i);
            put(u16,e,24,if(i==0) 1 else 0);
        }
        var zero = r.Builder.init(0,1,1,0);
        if (nonresident) {
            try zero.nonresidentRuns(0x20,&.{},&.{.{.lcn=12,.clusters=1}},0,4096,list.len,list.len);
            @memcpy(f.bytes[12*4096..][0..list.len],&list);
        } else try zero.resident(0x20,&.{},&list,false);
        try zero.nonresidentRuns(0x80,&.{},&.{.{.lcn=1,.clusters=2}},0,3*4096,3*4096,3*4096);
        try r.protect(&zero.b); @memcpy(f.bytes[4096..][0..1024],&zero.b);
        var extension = r.Builder.init(1,1,1,0);
        put(u64,&extension.b,32,(@as(u64,1)<<48)|(if(bad_base) @as(u64,2) else 0));
        try extension.nonresidentRuns(0x80,&.{},&.{.{.lcn=8,.clusters=1}},2,0,0,0);
        try r.protect(&extension.b); @memcpy(f.bytes[4096+1024..][0..1024],&extension.b);
        var tail = r.Builder.init(8,1,1,0);
        try tail.resident(0x80,&.{},"tail-data",false);
        try r.protect(&tail.b);@memcpy(f.bytes[8*4096..][0..1024],&tail.b);
        var volume=r.Builder.init(3,1,1,0);var info: [12]u8=@splat(0);info[8]=3;info[9]=1;
        try volume.resident(0x70,&.{},&info,false);try r.protect(&volume.b);
        @memcpy(f.bytes[4096+3*1024..][0..1024],&volume.b);
        var upcase=r.Builder.init(10,1,1,0);
        try upcase.nonresidentRuns(0x80,&.{},&.{.{.lcn=16,.clusters=32}},0,131072,131072,131072);
        try r.protect(&upcase.b);@memcpy(f.bytes[8*4096+2*1024..][0..1024],&upcase.b);
        for(0..65536) |i| put(u16,&f.bytes,65536+i*2,@intCast(if(i>='a' and i<='z') i-32 else if(i==0x105) 0x104 else i));
        return f;
    }
};

test "MiniOS MFT bootstrap resolves resident list and extension in known extent" {
    var fixture = try MftFixture.init(false,false,false,false);
    var fs = try nt.mountAllocated(fixture.reader(),.{.start_bytes=0,.size_bytes=fixture.bytes.len},libstd.testing.allocator);
    defer fs.deinit();
    try libstd.testing.expectEqual(@as(usize,2),fs.mftRunCount());
    var raw: [1024]u8 = undefined;
    _ = try nt.readRecord(&fs,fixture.reader(),8,&raw);
    const value=(try @import("record.zig").find(&raw,0x80,&.{})).?;
    try libstd.testing.expectEqualStrings("tail-data",try @import("record.zig").value(value.bytes));
}

test "MiniOS reads volume UpCase and refuses dirty or unknown NTFS state" {
    const r=@import("record.zig");
    var f=try MftFixture.init(true,false,false,false);
    var fs=try nt.mountAllocated(f.reader(),.{.start_bytes=0,.size_bytes=f.bytes.len},libstd.testing.allocator);
    try libstd.testing.expect(nt.namesEqual(&fs,&.{0x104,'.','I','S','O'},&.{0x105,'.','i','s','o'}));
    fs.deinit();
    const raw=f.bytes[4096+3*1024..][0..1024];
    try r.unprotect(raw);const attr=(try r.find(raw,0x70,&.{})).?;
    const value=try r.value(attr.bytes);MftFixture.put(u16,value,10,1);try r.protect(raw);
    try libstd.testing.expectError(error.UnsupportedVolumeState,nt.mountAllocated(f.reader(),.{.start_bytes=0,.size_bytes=f.bytes.len},libstd.testing.allocator));
    try r.unprotect(raw);const unknown=(try r.find(raw,0x70,&.{})).?;
    const unknown_value=try r.value(unknown.bytes);MftFixture.put(u16,unknown_value,10,0x80);try r.protect(raw);
    try libstd.testing.expectError(error.UnsupportedVolumeState,nt.mountAllocated(f.reader(),.{.start_bytes=0,.size_bytes=f.bytes.len},libstd.testing.allocator));
    try r.unprotect(raw);const a=(try r.find(raw,0x70,&.{})).?;
    const v=try r.value(a.bytes);MftFixture.put(u16,v,10,0);v[8]=4;try r.protect(raw);
    try libstd.testing.expectError(error.UnsupportedNtfsVersion,nt.mountAllocated(f.reader(),.{.start_bytes=0,.size_bytes=f.bytes.len},libstd.testing.allocator));
}

test "MiniOS MFT bootstrap reads nonresident ATTRIBUTE_LIST" {
    var fixture = try MftFixture.init(true,false,false,false);
    var fs = try nt.mountAllocated(fixture.reader(),.{.start_bytes=0,.size_bytes=fixture.bytes.len},libstd.testing.allocator);
    defer fs.deinit();
    try libstd.testing.expectEqual(@as(usize,2),fs.mftRunCount());
}

test "MiniOS MFT bootstrap refuses stale sequence foreign base and missing VCN" {
    for (0..3) |which| {
        var fixture = try MftFixture.init(true,which==0,which==1,which==2);
        try libstd.testing.expectError(error.AttributeListMismatch,nt.mountAllocated(fixture.reader(),.{.start_bytes=0,.size_bytes=fixture.bytes.len},libstd.testing.allocator));
    }
}
